public class Compiler_toSource_TriageGen0Test {

    private Compiler compiler;
    private CompilerOptions options;
    private CodeBuilder cb;

    @Mock
    private Node mockRoot;

    @Mock
    private JSDocInfo mockJSDocInfo;

    @Before
    public void setUp() {
        MockitoAnnotations.openMocks(this);
        compiler = new Compiler();
        options = new CompilerOptions();
        compiler.initOptions(options);
        cb = new CodeBuilder();
    }

    @Test
    public void testToSource_BasicNoOptions() {
        // Setup root to return some code via the internal toSource(root, sourceMap)
        // Note: In a real environment, we'd use a real Node/AST, but here we mock behavior.
        // Since toSource(root, sourceMap) is called internally, we assume the compiler 
        // is initialized enough to handle the root.

        // For this test to work without a full AST, we rely on the fact that 
        // if we don't set printInputDelimiter, it skips that block.

        // We need to mock the internal call behavior or use a real Node.
        // For unit testing this specific method, we simulate a simple script node.
        Node realRoot = new Node(Token.SCRIPT);
        realRoot.appendCode("var x = 1;");

        compiler.toSource(cb, 1, realRoot);

        assertEquals("var x = 1;", cb.toString());
    }

    @Test
    public void testToSource_WithDelimiterAndSourceName() {
        options.printInputDelimiter = true;
        options.inputDelimiter = "/* %name% %num% */";

        Node realRoot = new Node(Token.SCRIPT);
        realRoot.setProperty(Node.SOURCENAME_PROP, "test.js");
        realRoot.appendCode("var x = 1;");

        compiler.toSource(cb, 5, realRoot);

        // Expected: Delimiter + newline + code + semicolon (if not present)
        // The code "var x = 1;" does not end in ';', so it should append ';'
        String expected = "/* test.js 5 */\nvar x = 1;;";
        // Note: The logic appends ';' if code doesn't end in ';'. 
        // Our code 'var x = 1;' ends in ';', so it won't append.
        // Wait, the code is "var x = 1;". length-1 is ';'. hasSemiColon is true.

        assertEquals("/* test.js 5 */\nvar x = 1;", cb.toString());
    }

    @Test
    public void testToSource_WithLicense() {
        when(mockRoot.getJSDocInfo()).thenReturn(mockJSDocInfo);
        when(mockJSDocInfo.getLicense()).thenReturn("MIT");
        // Must be SCRIPT type for the logic to proceed if printInputDelimiter was true, 
        // but here it is false.

        Node realRoot = new Node(Token.SCRIPT);
        realRoot.appendCode("console.log(1);");

        compiler.toSource(cb, 1, realRoot);

        assertTrue(cb.toString().startsWith("/*\nMIT\n*/"));
        assertTrue(cb.toString().contains("console.log(1);"));
    }

    @Test
    public void testToSource_AppendsSemicolonWhenMissing() {
        Node realRoot = new Node(Token.SCRIPT);
        realRoot.appendCode("var x = 1"); // No semicolon

        compiler.toSource(cb, 1, realRoot);

        assertEquals("var x = 1;", cb.toString());
    }

    @Test
    public void testToSource_DoesNotAppendSemicolonWhenNewlineExists() {
        Node realRoot = new Node(Token.SCRIPT);
        realRoot.appendCode("var x = 1;\n"); // Ends in \n, but second last is ;

        compiler.toSource(cb, 1, realRoot);

        assertEquals("var x = 1;\n", cb.toString());
    }

    @Test
    public void testToSource_SourceMapPositionUpdate() {
        options.sourceMapOutputPath = "out.map";
        Node realRoot = new Node(Token.SCRIPT);
        realRoot.appendCode("var x = 1;");

        compiler.toSource(cb, 1, realRoot);

        // Verify sourceMap is not null and has been interacted with
        // (Indirectly checked by verifying no crash and logic flow)
        assertTrue(compiler.getSourceMap() != null);
    }

    @Test(expected = RuntimeException.class) // Preconditions.checkState throws IllegalStateException
    public void testToSource_ThrowsWhenNotScriptType() {
        options.printInputDelimiter = true;
        options.inputDelimiter = "%%";
        Node wrongNode = new Node(Token.EXPRESSION); 
        wrongNode.setProperty(Node.SOURCENAME_PROP, "test.js");

        compiler.toSource(cb, 1, wrongNode);
    }

    @Test(expected = RuntimeException.class)
    public void testToSource_ThrowsWhenSourceNameMissing() {
        options.printInputDelimiter = true;
        options.inputDelimiter = "%%";
        Node noNameNode = new Node(Token.SCRIPT);
        // SOURCENAME_PROP is not set

        compiler.toSource(cb, 1, noNameNode);
    }

    @Test
    public void testToSource_EmptyCodeDoesNotAppendSemicolon() {
        Node emptyRoot = new Node(Token.SCRIPT);
        // toSource(root, sourceMap) returns ""

        compiler.toSource(cb, 1, emptyRoot);

        assertEquals("", cb.toString());
    }
}
